import heapq

def shortest_path(start, end):
    heap = [(0, start[0], start[1])] # (cost, x, y)
    came_from = {} 
    cost_so_far = { start: 0 }

    while heap:
        (cost, x, y) = heapq.heappop(heap)

        if (x, y) == end:
            break

        for d in [[0, 1], [1, 0], [0, -1], [-1, 0]]:
            nx, ny = x + d[0], y + d[1]
            new_cost = cost + 1
            if (nx, ny) not in cost_so_far or new_cost < cost_so_far[(nx, ny)]:
                cost_so_far[(nx, ny)] = new_cost
                priority = new_cost
                heapq.heappush(heap, (priority, nx, ny))
                came_from[(nx, ny)] = (x, y)

    path = []
    current = end
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    path.reverse()

    return path

