class GenericIterator:
    """An iterator for a generic collection"""

    def __init__(self, collection):
        """The constructor takes a collection as argument"""
        self._collection = collection
        self._index = 0

    def __iter__(self):
        """Method to make this object usable in 'for' statement"""
        return self

    def __next__(self):
        """Method called to get the next item"""
        if self._index == len(self._collection):
            raise StopIteration
        result = self._collection[self._index]
        self._index += 1
        return result

